contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, uint delay, uint _am) public payable {
        require(amount >= 1 ether);
        require(delay >= 1);
        require(address(this).balance >= amount);
        uint t = block.timestamp + delay;
        c.Put{value: amount}(t);
        (uint unlockTime, uint bal) = c.Acc(address(this));
        require(bal == amount);
        require(unlockTime == t);
        require(block.timestamp < unlockTime, "time passed");
        bool reverted;
        try c.Collect(_am) { reverted = false; } catch { reverted = true; }
        // Deposit is unlocked? No: unlockTime is in the future, so Collect must revert
        // for any _am <= bal. To make the rule about balance too, unlock first by waiting
        // is impossible; instead assert the combined rule directly:
        assert(reverted == (_am > bal || block.timestamp <= unlockTime || bal < c.MinSum()));
    }
    receive() external payable {}
}

